using System;

namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class PaulValéry
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "La bêtise n'est pas mon fort.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Trouver n'est rien. Le difficile est de s'ajouter ce qu'on trouve.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L'expression d'un sentiment est toujours absurde.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "— Et le démon lui dit : donne-moi une preuve. Montre que tu es ''encore'' celui que tu as cru être.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Ce toit tranquille, où marchent des colombes,\nEntre les pins palpite, entre les tombes;\nMidi le juste y compose de feux\nLa mer, la mer, toujours recommencée !\nÔ récompense après une pensée\nQu’un long regard sur le calme des dieux !", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le vent se lève ! … Il faut tenter de vivre !\nL’air immense ouvre et referme mon livre", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Patience, patience,\nPatience dans l’azur !\nChaque atome de silence\nEst la chance d’un fruit mûr !", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Je n’aime pas trop les musées. Il y en a beaucoup d’admirables, il n’en est point de délicieux. Les idées de classement, de conservation et d’utilité publique, qui sont justes et claires, ont peu de rapport avec les délices.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L’Europe deviendra-t-elle ce qu’elle est en réalité, c’est-à-dire : un petit cap du continent asiatique, ou bien l’Europe restera-t-elle ce qu’elle paraît, c’est-à-dire : la partie précieuse de l’univers terrestre, la perle de la sphère, le cerveau d’un vaste corps ?", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "J'ai insisté (peut-être trop longuement) sur cet état critique, et je vous disais en substance qu'un désordre dont on ne peut imaginer le terme s'observe à présent dans tous les domaines. Nous le trouvons autour de nous comme en nous-mêmes, dans nos journées, dans notre allure, et jusque dans notre savoir.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Nous ne supportons plus la durée. Nous ne savons plus féconder l'ennui. Notre nature a horreur du vide, — ce vide sur lequel les esprits de jadis savaient peindre les images de leurs idéaux, leurs Idées, au sens de Platon.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "De là cette impression générale d'impuissance et d'incohérence qui domine dans nos esprits, qui les dresse, et les met dans cet état anxieux auquel nous ne pouvons ni nous accoutumer, ni prévoir un terme. D'un côté, un passé, qui n'est pas aboli ni oublié, mais un passé duquel nous ne pouvons à peu près rien tirer qui nous oriente dans le présent et nous donne à imaginer le futur. De l'autre, un avenir sans la moindre figure. Nous sommes, chaque jour, à la merci d'une intervention, d'un accident, matériel ou intellectuel.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Toute l'histoire humaine, en tant qu'elle manifeste la pensée, n'aura peut-être été que l'effet d'une sorte de crise, d'une poussée aberrante, comparable à quelque-une de ces brusques variations qui s'observent dans la nature et qui disparaissent aussi bizarrement qu'elles sont venues. Il y a eu des espèces instables, et des monstruosités de dimensions, de puissance, de complication, qui n'ont pas duré. Qui sait si toute notre culture n'est pas une hypertrophie, un écart, un développement insoutenable, qu'une ou deux centaines de siècles aura suffit à produire et à épuiser ?", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Tout se passe dans notre état de civilisation industrielle comme si, ayant inventé quelque substance, on inventait d'après ses propriétés une maladie qu'elle guérisse, une soif qu'elle puisse apaiser, une douleur qu'elle abolisse. On nous inocule donc, pour des fins d'enrichissement, des goûts et des désirs qui n'ont pas de racines dans notre vie physiologique profonde, mais qui résultent d'excitations psychiques ou sensorielles délibérément infligées. L'homme moderne s'enivre de dissipation. Abus de vitesse, abus de lumière, abus de toniques, de stupéfiants, d'excitants... Abus de fréquence dans les impressions ; abus de la diversité ; abus de merveilles ; abus de ces prodigieux moyens de déclenchement, par l'artifice desquels d'immenses effets sont mis sous les doigts des enfants. Toute vie actuelle est inséparable de ces abus.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L'espace libre et le temps libre ne sont plus que des souvenirs. Le temps libre dont il s'agit n'est pas le loisir tel qu'on l'entend d'habitude. [...] Mais je dis que le loisir intérieur, qui est tout autre chose que le loisir chronométrique, se perd. Nous perdons cette paix essentielle des profondeurs de l'être, cette absence sans prix, pendant laquelle les éléments les plus délicats de la vie se rafraîchissent et se réconfortent, pendant laquelle l'être, en quelque sorte, se lave du passé, du futur, de la conscience présente, des obligations suspendues et des attentes embusquées...", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Tout se borne à distribuer un savoir sans profondeur vivante, puisque nous admettons que nos vies publiques, nos rues, nos places soient déshonorées par des monuments qui offensent la vue et l'esprit ; que nos villes se développent dans le désordre, que les constructions de l'État ou des particuliers s'élèvent sans le moindre souci des exigences les plus simples du sentiment de la forme.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Mais cette fois, c'est notre sensibilité verbale qui s'est brutalisée, émoussée, dégradée... Le langage s'use en nous. L'épithète est dépréciée. L'inflation de la publicité a fait tomber à rien la puissance des adjectifs les plus forts. La louange et même l'injure sont dans la détresse ; on doit se fatiguer à chercher de quoi glorifier ou insulter les gens !", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Toutes les notions sur lesquelles nous avons vécu sont ébranlées. Les sciences mènent la danse. Le temps, l'espace, la matière sont comme le feu, et les catégories sont en fusion. Quant aux principes politiques et aux lois économiques, vous savez assez bien que Méphistophélès en personne semble aujourd'hui les avoir engagés dans la troupe de son sabbat.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L'individu, c'est aussi la liberté de l'esprit. Or nous avons vu que cette liberté (dans son sens le plus élevé) devient illusoire par le seul fait de la vie moderne. Nous sommes suggestionnés, harcelés, abêtis, en proie à toutes les contradictions, à toutes les dissonances qui déchirent le milieu de la civilisation actuelle. L'individu est déjà compromis, avant même que l'État l'ait entièrement assimilé.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Ce n'est qu'un jeu pour l'amateur de symétries historiques, c'est-à-dire imaginaires, que de démontrer que ces deux figures littéraires sont des figures semblables.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Dans les domaines de la création, qui sont aussi les domaines de l'orgueil, la nécessité de se distinguer est indivisible de l'existence même.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le poète se consacre et se consume donc à définir et à construire un langage dans le langage.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Mais un homme excité ne se paie pas de logique. Mon ami regardait mon calme comme un beau vase qui donne envie de le mettre en morceaux.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Nous autres, civilisations, nous savons maintenant que nous sommes mortelles.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "J’ai la manie étrange et dangereuse de vouloir, en toute matière, commencer par le commencement (c’est-à-dire par ''mon'' commencement individuel), ce qui revient à recommencer, à refaire toute une route, comme si tant d’autres ne l’avaient déjà tracée et parcourue… Cette route est celle que nous offre ou que nous impose le ''langage''. En toute question, et avant tout examen sur le fond, je regarde au langage ; j’ai coutume de procéder à la mode des chirurgiens qui purifient d’abord leurs mains et préparent leur champ opératoire. C’est ce que j’appelle le ''nettoyage de la situation verbale''.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "En vérité, il n’est pas de théorie qui ne soit un fragment, soigneusement préparé, de quelque autobiographie.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Maintenant, sur une immense terrasse d'Elsinore, qui va de Bâle à Cologne, qui touche aux sables de Nieuport, aux marais de la somme, aux craies de Champagne, aux granits d'Alsace, — l'Hamlet européen regarde des millions de spectres. Mais il est un Hamlet intellectuel. Il médite sur la vie et la mort des vérités.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Et de quoi était fait ce désordre de notre Europe mentale ? - De la libre coexistence dans tous les esprits cultivés des idées les plus dissemblables, des principes de vie et de connaissance les plus opposés. C'est là ce qui caractérise une époque ''moderne''. je ne déteste pas de généraliser la notion de moderne et de donner ce nom à certain mode d'existence au lieu d'en faire un pur synonyme de ''contemporain''. Il y a dans l'histoire des moments et des lieux où nous pourrions nous introduire, ''nous modernes'', sans troubler excessivement l'harmonie de ces temps-là, et sans y paraître des objets infiniment curieux, infiniment visibles, des être choquants, dissonants, inassimilables. Où notre entrée ferait le moins de sensation, là nous sommes presque chez nous. Il est clair que la Rome de Trajan, et que l'Alexandrie des Ptolémées nous absorberaient plus facilement que bien des localités moins reculées dans le temps, mais plus spécialisées dans un seul type de mœurs et entièrement consacrées à une seule race, à une seule culture et à une seul système de vie.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Adieu, fantômes ! Le monde n'a plus besoin de vous. Ni de moi. Le monde, qui baptise du nom de progrès sa tendance à une précision fatale, cherche à unir aux bienfaits de la vie les avantages de la mort. Une certaine confusion règne encore, mais encore un peu de temps et tout s'éclaircira ; nous verrons enfin apparaître le miracle d'une société animale, une parfaite et définitive fourmilière.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Une première pensée apparaît. L'idée de culture, d'intelligence, d’œuvres magistrales est pour nous dans une relation très ancienne - tellement ancienne que nous remontons rarement jusqu'à elle - avec l'idée d'Europe. Les autres parties du monde ont eu des civilisations admirables, des poètes du premier ordre, des constructeurs, et même des savants. Mais aucune partie du monde n'a possédé cette singulière propriété ''physique '': le plus intense pouvoir ''émissif ''uni au plus intense pouvoir ''absorbant''. Tout est venu à l'Europe et tout en est venu. Ou presque tout.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "- Mais l'Esprit européen - ou du moins ce qu'il contient de plus précieux - est-il totalement diffusible ? Le phénomène de la mise en exploitation du globe, le phénomène de l'égalisation des techniques et le phénomène démocratique, qui font prévoir une ''deminutio capitis'' de l'Europe, doivent-ils être pris comme décisions absolues du destin ? Ou avons-nous quelque liberté ''contre'' cette menaçante conjuration des choses ? C'est peut-être en cherchant cette liberté qu'on la crée. Mais pour une telle recherche, il faut abandonner pour un temps la considération des ensembles, et étudier dans l'individu pensant, la lutte de la vie personnelle avec la vie sociale.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le moi est haïssable... mais il s'agit de celui des autres.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Celui qui n'a pas nos répugnances nous répugne.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Chacune des qualités d'un esprit apporte des chances particulières d'erreur à la représentation du réel. Si tu es vif, le lent t'échappe.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le mensonge et la crédulité s'accouplent et engendrent l'Opinion.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Les vilaines pensées viennent du cœur.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Nous ne pensons que par hasard aux circonstances permanentes de notre vie ; nous ne les percevons qu'au moment où elles s'altèrent tout à coup.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Il n'y aurait qu'à jouir de ces beaux fruits de l'art historique et nulle objection ne s'élèverait contre leur usage, si la politique n'en était toute influencée. Le ''passé'', plus ou moins fantastique, ou plus ou moins organisé après coup, agit sur le futur avec une puissance comparable à celle du présent même. Les sentiments et les ambitions s'excitent de souvenirs de lecture, de souvenirs de souvenirs, bien plus qu'ils ne résultent de perceptions et de données actuelles. Le caractère réel de l'histoire est de prendre part à l'histoire même. L'idée du passé ne prend un sens et ne constitue une valeur que pour l'homme qui se trouve en soi-même une passion pour l'avenir.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le mot ''peuple'', par exemple, avait un sens précis quand on pouvait rassembler tous les citoyens d'une cité autour d'un tertre, dans un Champ de Mars. Mais l'accroissement du nombre, le passage de l'ordre des mille à celui des millions, a fait de ce mot un terme monstrueux dont le sens dépend de la phrase où il entre ; il désigne tantôt la totalité indistincte et jamais présente nulle part ; tantôt le plus grand nombre, opposé au nombre restreint des individus plus fortunés ou plus cultivés...", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Les plus instruits, les mieux placés peuvent même se dire, en évoquant ce qu'ils savent, en le comparant à ce qu'ils voient, que ce savoir ne fait qu'obscurcir le problème politique immédiat qui consiste après tout ''dans la détermination des rapports d'un homme avec la masse des hommes qu'il ne connaît pas''. Quelqu'un de sincère avec soi-même et qui répugne à spéculer sur des objets qui ne se raccordent pas rationnellement à sa propre expérience, à peine ouvre-t-il son journal, le voici qui pénètre dans un monde métaphysique désordonné. Ce qu'il lit, ce qu'il entend excède étrangement ce qu'il constate ou pourrait constater. S'il se résume son impression : ''Point de politique sans mythe'', pense-t-il.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Il n'y aura rien eu de plus sot dans toute l'histoire que la concurrence européenne en matière politique et économique, comparée, combinée et confrontée avec l'unité et l'alliance européenne en matière scientifique. Pendant que les efforts des meilleures têtes de l'Europe constituaient un capital immense de savoir utilisable, la tradition naïve de la politique historique de convoitise et d’arrière-pensées se poursuivait, et cet esprit de Petits-Européens livrait, par une sorte de trahison, à ceux mêmes qu'on entendait dominer, les méthodes et les instruments de puissance. La lutte pour des concessions ou pour des emprunts, pour introduire des machines ou des praticiens, pour créer des écoles ou des arsenaux - lutte qui n’est autre chose que le transport à longue distance des dissensions occidentales -, entraîne fatalement le retour de l’Europe au rang secondaire que lui assignent ses dimensions, et duquel les travaux et les échanges internes de son esprit l'avaient tirée. L'Europe n'aura pas eu la politique de sa pensée.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "À cause des sangs très disparates qu'elle a reçus, et dont elle a composé, en quelques siècles, une personnalité européenne si nette et si complète, productrice d’une culture et d’un esprit caractéristiques, la nation française fait songer à un arbre greffé plusieurs fois, de qui la qualité et la saveur de ses fruits résultent d’une heureuse alliance de sucs et de sèves très divers concourants à une même et indivisible existence.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L'accomplissement de nos désirs ne nous éloigne pas toujours de notre perte.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Une guerre dont l´issue n'a été due qu'a l'inégalité des puissances totales des adversaires est une guerre suspendue.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L’Histoire est le produit le plus dangereux que la chimie de l’intellect ait élaboré. Ses propriétés sont bien connues. Il fait rêver, il enivre les peuples, leur engendre de faux souvenirs, exagère leurs réflexes, entretient leurs vieilles plaies, les tourmente dans leur repos, les conduit au délire des grandeurs ou à celui de la persécution et rend les nations amères, superbes, insupportables et vaines. L'Histoire justifie ce que l'on veut. Elle n'enseigne rigoureusement rien, car elle contient des exemples de tout et donne des exemples de tout.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "La politique fut d'abord l'art d'empêcher les gens de se mêler de ce qui les regarde. À une époque suivante, on y adjoignit l'art de contraindre les gens à décider sur ce qu'ils n'entendent pas.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L'historien fait pour le passé ce que la tireuse de cartes fait pour le futur. Mais la sorcière s'expose à une vérification et non l'historien.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L'existence des voisins est la seule défense des nations contre une perpétuelle guerre civile.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L'homme qui a un emploi, l'homme qui gagne sa vie et qui peut consacrer une heure par jour à la lecture, qu'il la fasse chez lui ou dans le tramway ou dans le métro, cette heure est dévorée par les affaires criminelles, les niaiseries incohérentes, les ragots et les faits les moins divers, dont le pèle-mêle et l'abondance semblent fait pour ahurir et simplifier grossièrement les esprits. Notre homme est perdu pour les livres... Ceci est fatal et nous n'y pouvons rien. Tout ceci a pour conséquence une diminution réelle de culture, et en second lieu, une diminution réelle de la véritable liberté de l'esprit, car cette liberté exige au contraire un détachement, un refus de toutes ces sensations violentes ou incohérentes que nous recevons de la vie moderne, à chaque instant.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Comme on voit communément des anarchistes dans les partis de l'ordre et des organisateurs dans l'anarchie, je suggère un reclassement. Chacun se classerait dans le parti de ses dons. Il y a des créateurs, des conservateurs et des destructeurs par tempérament. Chaque individu serait mis dans son véritable parti, qui n'est point celui de ses paroles, ni de ses vœux, mais celui de son être et de ses modes d'agir et de réagir.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le résultat des luttes politiques est de troubler, de falsifier dans les esprits la notion de l'ordre d'importance des questions et de l'ordre d'urgence. Ce qui est vital est masqué par ce qui est de simple bien-être. Ce qui est d'avenir par l'immédiat. Ce qui est très nécessaire par ce qui est sensible. Ce qui est profond et lent par ce qui est excitant. Tout ce qui est de la ''politique pratique'' est nécessairement ''superficiel''.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Il est des hommes dont l'oreille, toute saine qu'elle est, ne distingue pas les sons d'avec les bruits.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Les petits faits inexpliqués contiennent toujours de quoi renverser toutes les explications des grands faits.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le réveil fait aux rêves une réputation qu'ils ne méritent pas.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "La richesse est une huile qui adoucit les machines de la vie.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Dieu créa l'homme, et ne le trouvant pas assez seul, il lui donne une compagne pour lui faire mieux sentir sa solitude.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Vieillir consiste à éprouver le changement du stable.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "La vie est à peine un peu plus vieux que la mort.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Les livres ont les mêmes ennemis que l'homme : le feu, l'humide, les bêtes, le temps; et leur propre contenu.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Crois, ou je te tue éternellement.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le pouvoir sans abus perd le charme.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Il est impossible de dire au Monde, au Corps : je ne veux rien de toi, mais ne veuille rien de moi.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le poème — cette hésitation prolongée entre le son et le sens.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "On n'est jamais assez content de soi pour se livrer à fond.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le sujet d'un ouvrage est à quoi se réduit un mauvais ouvrage.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Pamphlétaires, orateurs, violents, forcenés, qui vociférez, dites, ne sentez-vous jamais que tout homme qui crie est sur le point de faire semblant de crier ?", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le plaisir qu'il y a à comprendre certains raisonnements délicats dispose l'esprit en faveur de leurs conclusions.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Par le moyen de l'homme, l'impossible presse sur le réel.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Entendez la parole la plus étrange : ''Il y aura des hommes après nous''.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Être soi-même!... Mais soi-même en vaut-il la peine?", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Offense-moi, - pour me donner la force de te tuer.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Tous nos ennemis sont mortels.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Quand nous parvenons au but, nous croyons que le chemin a été le bon.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Un homme absorbé dans la plus profonde méditation. Son visage est vide, rien n'est écrit par ses traits. Comment peut-on être si loin de ce que l'on a de plus près?", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le simple est toujours faux. Ce qui ne l'est pas est inutilisable.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L´espoir fait vivre, mais comme sur une corde raide.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Nous avons de quoi saisir ce qui n'existe pas et de quoi ne pas voir ce qui nous crève les yeux.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L'homme de génie est qui m'en donne.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le pauvre est le produit d'une transformation facile effectuée sur le riche; le riche, celui d´une transformation difficile effectuée sur le pauvre.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Un homme compétent est un homme qui se trompe selon les règles.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Proverbe pour les puissants: Si quelqu'un te léche les bottes, mets-lui le pied dessus avant qu'il ne commence à te mordre.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L'individu est la plus étrange création de l´homme.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Dieu a tout fait de rien. Mais le rien perce.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Il y a de la pauvreté d'esprit à être toujours d'accord avec soi-même.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Je sentais que ce maître de ses moyens, ce possesseur du dessin, des images, du calcul, avait trouvé l’attitude centrale à partir de laquelle les entreprises de la connaissance et les opérations de l’art sont également possibles ; les échanges heureux entre l’analyse et les actes, singulièrement probables : pensée merveilleusement excitante. Mais pensée trop immédiate, — pensée sans valeur, — pensée infiniment répandue, — et pensée bonne pour parler, non pour écrire.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Si légèrement que je l’eusse étudié, ses dessins, ses manuscrits m’avaient comme ébloui. De ces milliers de notes et de croquis, je gardais l’impression extraordinaire d’un ensemble hallucinant d’étincelles arrachées par les coups les plus divers à quelque fantastique fabrication. Maximes, recettes, conseils à soi, essais d’un raisonnement qui se reprend ; parfois une description achevée ; parfois il se parle et se tutoie… Mais je n’avais nulle envie de redire qu’il fut ceci et cela : et peintre, et géomètre, et… Et, d’un mot, l’artiste du monde même. Nul ne l’ignore.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Il reste d’un homme ce que donnent à songer son nom et les œuvres qui font de ce nom un signe d’admiration, de haine ou d’indifférence.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "C’est à l’univers qu’il songe toujours, et à la rigueur.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Il y eut une fois Quelqu’un qui pouvait regarder le même spectacle ou le même objet, tantôt comme l’eût regardé un peintre, et tantôt en naturaliste ; tantôt comme un physicien, et d’autres fois, comme un poète : et aucun de ces regards n’était superficiel.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Les recherches insensées sont parentes des découvertes imprévues.", Author = "Paul Valéry" },
        };
    }
}